// Minimal fake of @lynx-js/rspeedy's public loadConfig() — just enough
// shape to exercise resolveLynxOutputDir's real resolution path (the
// exports-map subpath walk, the dynamic import, the field extraction)
// without pulling the real, heavy rspeedy package into this plugin's
// devDependencies just to test it.
export async function loadConfig() {
  return {
    content: {
      output: {
        distPath: {
          root: './custom-dir-from-fake',
        },
      },
    },
    configPath: 'lynx.config.ts',
  }
}
